-- =============================================================================
-- 525 — LE CAHIER D'EXERCICES DE 1RE (partie 13)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 525 --niveau 1re --fichiers francais.n14a,francais.n14b,francais.n15a,francais.n15b,francais.n16a --suffixe 13 > supabase/contenu/525_exercices_1re_13.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n14a           18 exercices · 6 chapitres
--   francais.n14b           18 exercices · 6 chapitres
--   francais.n15a           18 exercices · 6 chapitres
--   francais.n15b           18 exercices · 6 chapitres
--   francais.n16a           18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b91aed45-2aff-592c-9733-27fc3c012c1c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une invitation au voyage symboliste","competence":"analyser-document","situation":"Tu prépares ta fiche sur *Le Voyage d’Urien*. Une invitation de librairie, imaginée pour l’exercice, résume la carte d’identité du livre : lis-la, puis relève ce qu’il faut savoir.","documents":[{"id":"inv","type":"fiche","modele":"invitation","entete":"Le Voyage d’Urien","sousTitre":"André Gide — 1893","emoji":"⛵","lignes":[{"texte":"Genre","valeur":"Récit symboliste en prose","id":"z1"},{"texte":"Illustré par","valeur":"Maurice Denis","id":"z2"},{"texte":"Cercle fréquenté par Gide","valeur":"Les mardis de Mallarmé","id":"z3"},{"texte":"Courant","valeur":"?","id":"z4"},{"texte":"Le voyage","valeur":"Trois grandes mers","id":"z5"}],"pied":"Un livre de jeunesse, pensé comme un objet d’art","teinte":"violet","source":"Document imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui nomme le peintre de l’édition originale.","aide":"Cherche les mots « Illustré par ».","type":"zone","document":"inv","multiple":false},{"enonce":"La case « ? » du courant : à quel mouvement ce livre se rattache-t-il ?","aide":"Regarde le cercle que fréquente Gide : celui de Mallarmé.","type":"choix","options":[{"id":"a","texte":"Le naturalisme"},{"id":"b","texte":"Le symbolisme"},{"id":"c","texte":"Le romantisme"},{"id":"d","texte":"Le surréalisme"}],"multiple":false},{"enonce":"Complète la carte d’identité du livre.","aide":"La date et le nom du peintre sont sur l’invitation ; l’âge de Gide, tu l’as dans le cours.","type":"trous","segments":["Le livre paraît en ",0,", avec des lithographies de ",1," ; Gide a alors ",2," ans."],"banque":["Maurice Denis","vingt-trois","1893","1891","Mallarmé","trente"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’édition originale de 1893 est ornée de lithographies de **Maurice Denis**, peintre du groupe nabi."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le livre naît dans le cercle de Mallarmé, comme objet d’art : c’est un récit **symboliste**."},{"cle":{"type":"trous","trous":[["1893"],["maurice denis"],["vingt trois","23"]]},"affichage":"1893 · Maurice Denis · vingt-trois","explication":"Le livre paraît en **1893**, orné par **Maurice Denis**, quand Gide a **vingt-trois** ans."}]$ex$::jsonb),
  ('b91aed45-2aff-592c-9733-27fc3c012c1c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"De la mer des plaisirs au pôle blanc","competence":"analyser-document","situation":"Urien et ses compagnons traversent trois mers avant le pôle. Suis leur route sur la chaîne, retrouve l’étape manquante, puis le dénouement.","documents":[{"id":"route","type":"chaine","titre":"La route du voyage","disposition":"colonne","noeuds":[{"id":"z1","texte":"Océan pathétique : tentations et plaisirs"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Mer glaciale : blanche, vers un pôle mystérieux"},{"id":"z4","texte":"Au pôle : « HIC DESPERATUS »"}],"liens":[{"de":"z1","a":"z2","texte":"puis"},{"de":"z2","a":"z3","texte":"puis"},{"de":"z3","a":"z4","texte":"enfin"}]}],"questions":[{"enonce":"Quelle mer occupe la case « ? », entre les plaisirs et la glace ?","aide":"Après les plaisirs, l’équipage s’enlise : la mer ne bouge plus.","type":"choix","options":[{"id":"a","texte":"La mer Égée, claire et mouvante"},{"id":"b","texte":"La mer des Sargasses, immobile et morne"},{"id":"c","texte":"La mer du Nord, agitée et sombre"},{"id":"d","texte":"La mer Rouge, brûlante et vive"}],"multiple":false},{"enonce":"Touche l’étape où le voyage devient blanc et pur.","aide":"Cherche le mot qui évoque la glace.","type":"zone","document":"route","multiple":false},{"enonce":"Remets dans l’ordre les derniers temps du récit.","aide":"On passe de l’inscription à la découverte, puis à l’aveu final en vers.","type":"ordre","items":[{"id":"a","texte":"Sous la glace, ils découvrent un cadavre"},{"id":"b","texte":"Le cadavre tient un papier tout blanc"},{"id":"c","texte":"Les voyageurs lisent « HIC DESPERATUS » au pôle"},{"id":"d","texte":"L’Envoi avoue que le voyage a été rêvé"}]},{"enonce":"Que représentent les escales du voyage ?","aide":"Pense aux plaisirs, à l’enlisement, à la pureté : ce sont des mouvements intérieurs.","type":"choix","options":[{"id":"a","texte":"Des étapes d’une expédition scientifique"},{"id":"b","texte":"Des souvenirs d’enfance de l’auteur"},{"id":"c","texte":"Des ports réellement visités par Gide"},{"id":"d","texte":"Des états d’âme plus que des lieux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Entre l’Océan pathétique et la mer glaciale vient la **mer des Sargasses**, immobile et morne, où l’équipage s’enlise."},{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est la **mer glaciale** : blanche et pure, elle mène vers un pôle mystérieux."},{"cle":{"type":"ordre","ids":["c","a","b","d"]},"explication":"On lit d’abord l’inscription, puis on trouve le **cadavre** et son **papier blanc** ; l’**Envoi** en vers révèle enfin que tout était rêvé."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les escales sont des **états d’âme** plus que des lieux : le paysage est allégorique."}]$ex$::jsonb),
  ('b91aed45-2aff-592c-9733-27fc3c012c1c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un voyage dans la chambre de ses pensées","competence":"argumenter","situation":"Lina et Théo se disputent sur *Le Voyage d’Urien* : récit de voyage ou récit intérieur ? Lis leur échange et un pastiche écrit pour l’exercice, puis tranche.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"Une escale, à la manière de Gide","blocs":["Nous quittâmes la côte sans l’avoir décidé. Chaque escale ressemblait à un désir : on y descendait par envie, on y restait par faiblesse, et l’un d’entre nous manquait à l’appel au départ.","Puis la mer devint blanche. Aucun port n’était en vue, mais personne ne demanda où nous allions : il suffisait de marcher vers le froid."],"source":"Texte écrit pour l’exercice, à la manière du *Voyage d’Urien* de Gide"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Gide raconte un vrai tour des mers : il a tout vu de ses yeux."},{"qui":"Théo","texte":"Non : les escales sont des états d’âme, et l’Envoi final avoue que le voyage a été rêvé."},{"qui":"Lina","texte":"Alors pourquoi décrire autant de paysages ?"},{"qui":"Théo","texte":"Parce que chaque paysage signifie un désir ou une tentation au lieu de simplement décrire."}]}],"questions":[{"enonce":"Touche les deux noms qui montrent que l’escale est un mouvement intérieur, non un lieu.","aide":"Cherche ce qui pousse à descendre et ce qui fait rester.","type":"zone","document":"texte","multiple":true},{"enonce":"Quelle lecture le débat et le texte confirment-ils ?","aide":"Relis la réponse de Théo, puis le pastiche : qu’est-ce qui fait descendre à terre ?","type":"choix","options":[{"id":"a","texte":"Le texte relate une expédition à but scientifique"},{"id":"b","texte":"Les escales décrivent des ports visités par Gide"},{"id":"c","texte":"Les compagnons sont de simples marins sans valeur"},{"id":"d","texte":"Les escales traduisent des désirs : le voyage est intérieur"}],"multiple":false},{"enonce":"Relie chaque procédé du livre à son effet.","aide":"Demande-toi à chaque fois : que lit-on à travers l’image ?","type":"association","gauche":[{"id":"g0","texte":"Les paysages allégoriques"},{"id":"g1","texte":"Le « nous » d’Urien"},{"id":"g2","texte":"L’Envoi final en vers"},{"id":"g3","texte":"Les trois mers successives"}],"droite":[{"id":"d0","texte":"Elles scandent une quête spirituelle"},{"id":"d1","texte":"Les compagnons figurent les désirs d’une seule âme"},{"id":"d2","texte":"Il révèle que tout a été rêvé"},{"id":"d3","texte":"Le paysage signifie au lieu de décrire"}]},{"enonce":"À quoi sert un voyage imaginaire, d’après cette œuvre ?","aide":"Le cours dit : explorer l’intériorité, pas le monde.","type":"choix","options":[{"id":"a","texte":"À remplacer la littérature par la science"},{"id":"b","texte":"À explorer l’intériorité plutôt que le monde"},{"id":"c","texte":"À décrire fidèlement des lieux très lointains"},{"id":"d","texte":"À préparer une véritable expédition en mer"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m23"]},"explication":"On descend par **envie**, on reste par **faiblesse** : l’escale est un désir, pas un port."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le texte et Théo s’accordent : les escales sont des **désirs**, et le voyage est **intérieur**."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"Le paysage **signifie**, le « nous » rassemble les **désirs**, l’Envoi **dévoile le rêve**, les mers **scandent la quête**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le voyage imaginaire sert à explorer **l’intériorité** : c’est la leçon du récit symboliste."}]$ex$::jsonb),
  ('f5e2253b-03dd-5333-9a15-e67c4c30e960'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le poète que personne n’a lu","competence":"lire-tableau","situation":"Pour ta fiche sur *Les Amours jaunes*, un tableau résume le destin de Corbière. Lis-le, complète la case manquante, puis retrouve qui est qui.","documents":[{"id":"faits","type":"tableau","titre":"Corbière en quelques faits","colonnes":["Fait","Le détail"],"lignes":[["L’auteur","Tristan Corbière (1845-1875)"],["Son père","Édouard Corbière, capitaine et auteur de romans maritimes"],["La publication","À compte d’auteur, en 1873"],["Son accueil","?"],["Son sauvetage","Verlaine, dans *Les Poètes maudits*"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui dit comment le recueil a été publié.","aide":"Cherche l’année 1873.","type":"zone","document":"faits","multiple":false},{"enonce":"Que met-on dans la case « ? » : comment le recueil est-il accueilli ?","aide":"Corbière meurt jeune et presque sans lecteurs.","type":"choix","options":[{"id":"a","texte":"Il passe totalement inaperçu"},{"id":"b","texte":"Il est interdit par la censure"},{"id":"c","texte":"Il connaît un triomphe de librairie"},{"id":"d","texte":"Il est salué par les Parnassiens"}],"multiple":false},{"enonce":"Combien d’années séparent la parution du recueil de la mort de Corbière ?","aide":"Repère les deux années du tableau et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque nom à son rôle.","aide":"Un nom d’écrivain, un père, un lieu : chacun a sa phrase dans le cours.","type":"association","gauche":[{"id":"g0","texte":"Édouard Corbière"},{"id":"g1","texte":"Verlaine"},{"id":"g2","texte":"Laforgue"},{"id":"g3","texte":"Roscoff"}],"droite":[{"id":"d0","texte":"Le père, capitaine et romancier de la mer"},{"id":"d1","texte":"Il sauve Corbière de l’oubli"},{"id":"d2","texte":"Le port breton où vit Tristan"},{"id":"d3","texte":"Il reconnaît la modernité du poète"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le recueil paraît **à compte d’auteur**, en 1873 : l’auteur paie lui-même l’impression."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le recueil passe **totalement inaperçu** : quelques exemplaires seulement sont vendus."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 ans","explication":"1875 − 1873 = **2 ans** : le poète meurt deux ans après sa seule publication."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**Édouard** est le père, **Verlaine** le sauveur, **Laforgue** un lecteur moderne, **Roscoff** le port du poète."}]$ex$::jsonb),
  ('f5e2253b-03dd-5333-9a15-e67c4c30e960'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les rubriques d’un recueil rebelle","competence":"lire-tableau","situation":"Le recueil est rangé en sections aux noms étranges. Lis ce tableau, puis une courte notice écrite pour l’exercice, et reconstitue ce que contient chaque partie.","documents":[{"id":"sections","type":"tableau","titre":"Quelques sections du recueil","colonnes":["Section","Ce qu’on y trouve"],"lignes":[["« Armor »","La Bretagne des pardons et des mendiants"],["« Gens de mer »","?"],["« Raccrocs »","Des pièces diverses, parfois écrites en Italie"],["« Rondels pour après »","?"]],"enteteLignes":true},{"id":"notice","type":"texte","genre":"article","titre":"Le recueil en bref","blocs":["Corbière publie son unique recueil à compte d’auteur. Presque personne ne le lit.","Le titre joue sur une expression : on dit d’un rire forcé, amer, qu’il est « jaune ». Chez Corbière, ce rire se tourne contre soi."],"source":"Notice écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui disent que l’auteur a payé lui-même la publication.","aide":"Cherche l’expression qui suit « à ».","type":"zone","document":"notice","multiple":true},{"enonce":"Que met-on dans la case « ? » de « Gens de mer » ?","aide":"Le titre de la section annonce ceux qui vivent sur la mer.","type":"choix","options":[{"id":"a","texte":"Les marins, loin des clichés romantiques"},{"id":"b","texte":"La Bretagne des pardons et des mendiants"},{"id":"c","texte":"La mort, sur un ton de berceuse"},{"id":"d","texte":"L’autoportrait ironique et l’amour raté"}],"multiple":false},{"enonce":"Touche le mot qui dit contre qui le rire « jaune » est tourné.","aide":"C’est la clé du titre : une ironie qui revient vers celui qui parle.","type":"zone","document":"notice","multiple":false},{"enonce":"Que met-on dans la case « ? » de « Rondels pour après » ?","aide":"« Pour après » : après quoi ? Pense à ce qui vient quand le poème s’achève.","type":"choix","options":[{"id":"a","texte":"La Bretagne des pardons et des mendiants"},{"id":"b","texte":"La mort, sur un ton de berceuse"},{"id":"c","texte":"Les marins, loin des clichés romantiques"},{"id":"d","texte":"Des pièces écrites en Italie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m7","m8"]},"explication":"L’expression est **à compte d’auteur** : Corbière finance son propre livre."},{"cle":{"type":"choix","ids":["a"]},"explication":"« Gens de mer » montre les **marins**, loin des clichés romantiques."},{"cle":{"type":"zone","ids":["m38"]},"explication":"Le rire jaune de Corbière se tourne contre **soi** : c’est une ironie dirigée contre le poète lui-même."},{"cle":{"type":"choix","ids":["b"]},"explication":"« Rondels pour après » aborde la **mort**, sur un ton de **berceuse**."}]$ex$::jsonb),
  ('f5e2253b-03dd-5333-9a15-e67c4c30e960'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Se moquer de sa propre épitaphe","competence":"argumenter","situation":"Pour un sujet de dissertation sur le lyrisme contesté, tu t’appuies sur un vers célèbre de Corbière. Lis-le, puis construis ton argument.","documents":[{"id":"vers","type":"texte","genre":"poeme","titre":"Un vers d’« Épitaphe »","blocs":["Il se tua d’ardeur, ou mourut de paresse."],"source":"Tristan Corbière, « Épitaphe », *Les Amours jaunes* (1873)"},{"id":"these","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le lyrisme de Corbière est contesté","Le moi est là, mais il se moque de sa propre plainte","?"],["L’ironie est son arme","Le poème se retourne contre lui-même","L’autoportrait : laid, malade, raté"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux expressions qui s’opposent dans ce vers.","aide":"Une cause qui suppose beaucoup d’énergie, une autre qui suppose son contraire.","type":"zone","document":"vers","multiple":true},{"enonce":"Un poète qui écrit sa propre épitaphe en hésitant entre ces deux causes : que fait-il de sa mort ?","aide":"Le vers hésite entre deux causes opposées : le ton est-il grave ?","type":"choix","options":[{"id":"a","texte":"Il la pleure dans un lyrisme sincère"},{"id":"b","texte":"Il la célèbre comme un exploit héroïque"},{"id":"c","texte":"Il s’en moque, par ironie contre lui-même"},{"id":"d","texte":"Il la présente comme une vengeance"}],"multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Il faut un exemple où le moi est présent mais ironique envers lui-même.","type":"choix","options":[{"id":"a","texte":"« Épitaphe », où le poète se moque de sa propre mort"},{"id":"b","texte":"Un poème breton sans la moindre ironie"},{"id":"c","texte":"Une plainte amoureuse sincère, comme chez Lamartine"},{"id":"d","texte":"Un récit épique de combat naval"}],"multiple":false},{"enonce":"Relie chaque arme de Corbière à son effet.","aide":"Chaque procédé a une conséquence sur la façon dont on lit le poème.","type":"association","gauche":[{"id":"g0","texte":"L’ironie, l’argot, les jeux de mots"},{"id":"g1","texte":"Les tirets et les ruptures de ton"},{"id":"g2","texte":"L’autoportrait laid, malade et raté"}],"droite":[{"id":"d0","texte":"Rien ne s’installe"},{"id":"d1","texte":"Il refuse la pose du poète"},{"id":"d2","texte":"Le poème se retourne contre lui-même"}]},{"enonce":"Selon le cours, quel poète peut-on opposer à Corbière sur le lyrisme ?","aide":"On oppose un lyrisme sincère à un lyrisme contesté.","type":"choix","options":[{"id":"a","texte":"Laforgue, au lyrisme ironique"},{"id":"b","texte":"Rimbaud, poète voyant"},{"id":"c","texte":"Lamartine, au lyrisme sincère"},{"id":"d","texte":"Ronsard, poète du sonnet"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m4","m8"]},"explication":"**D’ardeur** et **paresse** s’opposent : le poète ne sait même pas de quoi il est mort, et il en rit."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’hésitation est comique : le poète **se moque de lui-même**, c’est le rire jaune."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le vers d’**« Épitaphe »** illustre la thèse : le « moi » s’y montre, mais pour se moquer de lui-même."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"L’**ironie** retourne le poème, les **ruptures** empêchent qu’il s’installe, l’**autoportrait** refuse la pose du poète."},{"cle":{"type":"choix","ids":["c"]},"explication":"On l’oppose à **Lamartine**, dont le lyrisme est sincère ; on le rapproche de Laforgue."}]$ex$::jsonb),
  ('5895c488-1aa0-5891-8a83-d12868ddc0b7'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Trois cycles, trois femmes","competence":"lire-tableau","situation":"Ronsard a donné plusieurs recueils d’amour. Lis ce tableau de ses trois cycles, complète-le, puis relie chaque femme à ce qu’on sait d’elle.","documents":[{"id":"cycles","type":"tableau","titre":"Les trois cycles amoureux","colonnes":["Cycle","Date","Sa manière"],"lignes":[["Les Amours de Cassandre","1552","Sonnets pétrarquistes : amour idéal et inaccessible"],["Les Amours de Marie","1555-1556","?"],["Les Sonnets pour Hélène","1578","Le poète vieillissant s’adresse à une dame de la cour"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la date du premier cycle, celui de Cassandre.","aide":"Cherche la ligne qui porte le nom de Cassandre.","type":"zone","document":"cycles","multiple":false},{"enonce":"Combien d’années séparent les *Amours de Cassandre* des *Sonnets pour Hélène* ?","aide":"Soustrais les deux dates du tableau.","type":"nombre","unite":"ans"},{"enonce":"Que met-on dans la case « ? » : la manière du cycle de Marie ?","aide":"Après les sonnets savants de Cassandre, Ronsard change de ton pour une jeune paysanne.","type":"choix","options":[{"id":"a","texte":"Le style mythologique, précieux et savant"},{"id":"b","texte":"Le style satirique contre la cour"},{"id":"c","texte":"Le grand style épique des batailles"},{"id":"d","texte":"Le « beau style bas » : plus simple et plus sensuel"}],"multiple":false},{"enonce":"Relie chaque nom à ce qu’on sait de lui ou d’elle.","aide":"Chaque nom a une phrase dans le cours sur les trois femmes et la Pléiade.","type":"association","gauche":[{"id":"g0","texte":"Cassandre"},{"id":"g1","texte":"Marie"},{"id":"g2","texte":"Hélène"},{"id":"g3","texte":"Du Bellay"}],"droite":[{"id":"d0","texte":"Jeune Angevine de condition modeste"},{"id":"d1","texte":"Rencontrée à Blois en 1545"},{"id":"d2","texte":"Auteur de la *Défense et illustration* (1549)"},{"id":"d3","texte":"Dame d’honneur de Catherine de Médicis"}]}]}$ex$::jsonb,
