  ('5895c488-1aa0-5891-8a83-d12868ddc0b7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le poète sourd de la Pléiade","competence":"analyser-texte","situation":"Une notice écrite pour l’exercice présente le parcours de Ronsard avant ses grands recueils. Lis-la, repère les mots clés, puis range les cycles et leurs poèmes.","documents":[{"id":"notice","type":"texte","genre":"article","titre":"Un poète devenu chef d’école","blocs":["Devenu sourd très jeune, Ronsard renonce à la carrière des armes pour l’étude des Anciens au collège de Coqueret.","Avec Du Bellay, il fonde la Pléiade. En 1549, la *Défense et illustration de la langue française* donne le programme : imiter les Anciens et Pétrarque pour enrichir la langue."],"source":"Notice écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui explique pourquoi Ronsard renonce aux armes.","aide":"Quel handicap l’écarte du métier de soldat ?","type":"zone","document":"notice","multiple":false},{"enonce":"Touche le nom du groupe qu’il fonde avec Du Bellay.","aide":"Ce nom évoque une constellation de sept étoiles.","type":"zone","document":"notice","multiple":false},{"enonce":"Remets ses trois cycles amoureux dans l’ordre de leur parution.","aide":"Du plus ancien au plus tardif : 1552, 1555-1556, 1578.","type":"ordre","items":[{"id":"a","texte":"Les Amours de Marie"},{"id":"b","texte":"Les Sonnets pour Hélène"},{"id":"c","texte":"Les Amours de Cassandre"}]},{"enonce":"Range chaque poème dans l’ensemble auquel il appartient.","aide":"Un poème est une déploration, un autre s’adresse à une dame qui vieillira, le troisième est une ode.","type":"categories","categories":[{"id":"c0","texte":"Cycle d’Hélène"},{"id":"c1","texte":"Mort de Marie"},{"id":"c2","texte":"Odes"}],"items":[{"id":"i0","texte":"« Mignonne, allons voir si la rose… »"},{"id":"i1","texte":"« Comme on voit sur la branche… »"},{"id":"i2","texte":"« Quand vous serez bien vieille… »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"Devenu **sourd** jeune, Ronsard se tourne vers l’étude."},{"cle":{"type":"zone","ids":["m26"]},"explication":"Ronsard et Du Bellay fondent la **Pléiade**."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Cassandre (**1552**), puis Marie (**1555-1556**), puis Hélène (**1578**)."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0"}},"explication":"« Quand vous serez bien vieille » appartient au cycle d’**Hélène**, « Comme on voit sur la branche » pleure **Marie**, « Mignonne, allons voir… » vient des **Odes**."}]$ex$::jsonb),
  ('5895c488-1aa0-5891-8a83-d12868ddc0b7'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une menace en forme de sonnet","competence":"argumenter","situation":"Le carpe diem est-il une consolation ou une arme ? Lis les premiers vers d’un sonnet pour Hélène, puis son dernier vers (orthographe modernisée), et tranche.","documents":[{"id":"debut","type":"texte","genre":"poeme","titre":"Le début du sonnet","blocs":["Quand vous serez bien vieille, au soir, à la chandelle,","Assise auprès du feu, dévidant et filant,","Direz, chantant mes vers, en vous émerveillant :","« Ronsard me célébrait du temps que j’étais belle. »"],"source":"Pierre de Ronsard, *Sonnets pour Hélène* (1578), vers 1 à 4, orthographe modernisée"},{"id":"fin","type":"texte","genre":"article","titre":"Le dernier vers","blocs":["« Cueillez dès aujourd’hui les roses de la vie. »"],"source":"Pierre de Ronsard, *Sonnets pour Hélène* (1578), dernier vers, orthographe modernisée"}],"questions":[{"enonce":"Touche l’adjectif qui projette la belle dans l’avenir.","aide":"Le poète imagine la dame au soir de sa vie.","type":"zone","document":"debut","multiple":false},{"enonce":"Touche les deux participes présents qui montrent la vieille femme au travail.","aide":"Ce sont deux gestes de fileuse, au coin du feu.","type":"zone","document":"debut","multiple":true},{"enonce":"Relie chaque procédé du sonnet à son effet.","aide":"Demande-toi ce que chaque temps ou mode verbal fait imaginer à la belle.","type":"association","gauche":[{"id":"g0","texte":"Le futur « Quand vous serez »"},{"id":"g1","texte":"La citation « Ronsard me célébrait… »"},{"id":"g2","texte":"L’impératif « Cueillez »"}],"droite":[{"id":"d0","texte":"La gloire du poète seule immortalise la belle"},{"id":"d1","texte":"Il transforme la menace en invitation à aimer aujourd’hui"},{"id":"d2","texte":"Il projette la belle dans sa vieillesse"}]},{"enonce":"Selon le cours, que représente le carpe diem dans ce sonnet ?","aide":"Le cours parle d’une « arme » du poète pour convaincre.","type":"choix","options":[{"id":"a","texte":"Une stratégie : le poète menace la belle de vieillir"},{"id":"b","texte":"Une plainte sur la mort de Marie, première muse"},{"id":"c","texte":"Une consolation offerte à la belle qui vieillira"},{"id":"d","texte":"Un renoncement au plaisir conseillé à la belle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"L’adjectif **vieille** place la belle devant l’image de son propre âge."},{"cle":{"type":"zone","ids":["m14","m16"]},"explication":"**Dévidant** et **filant** : la belle, devenue vieille, file la laine près du feu."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le **futur** menace, la **citation** vante la gloire du poète, l’**impératif** pousse à aimer **maintenant**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le carpe diem est une **stratégie de séduction** : le poète menace la belle de la vieillesse pour la convaincre d’aimer."}]$ex$::jsonb),
  ('3b54cb3b-8deb-543c-9abc-12d5f261c7bb'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le précepteur et son élève","competence":"se-reperer-temps","situation":"Fénelon écrit pour un prince. Place les grandes dates de sa vie sur la frise, puis retrouve ce qu’elles disent de la naissance du *Télémaque*.","documents":[{"id":"frise","type":"frise","titre":"Fénelon et son livre","debut":1650,"fin":1720,"pas":10,"evenements":[{"id":"z1","date":1651,"nom":"Naissance"},{"id":"z2","date":1689,"nom":"Précepteur"},{"id":"z3","date":1697,"nom":"Exil"},{"id":"z4","date":1699,"nom":"Télémaque publié"},{"id":"z5","date":1715,"nom":"Mort"}]}],"questions":[{"enonce":"Touche l’année où Fénelon devient le précepteur du duc de Bourgogne.","aide":"Cherche l’événement dont le nom désigne son métier d’éducateur.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’exil de Fénelon de la publication du livre ?","aide":"Repère « Exil » et « Télémaque publié » sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Complète la carte d’identité du livre.","aide":"Tout est dans le cours, au début de la fiche.","type":"trous","segments":["Fénelon, ",0," de Cambrai, écrit pour le duc de ",1,", petit-fils de ",2,"."],"banque":["Louis XIV","archevêque","Louis XV","évêque","Anjou","Bourgogne"]},{"enonce":"Comment le livre est-il publié en 1699 ?","aide":"L’exil date de 1697 : l’auteur n’est plus en position de décider.","type":"choix","options":[{"id":"a","texte":"Sous le nom d’un autre écrivain"},{"id":"b","texte":"Sans l’accord de son auteur"},{"id":"c","texte":"À la demande du roi Louis XIV"},{"id":"d","texte":"À compte d’auteur, à Cambrai"}],"multiple":false}]}$ex$::jsonb,
