  ('3b54cb3b-8deb-543c-9abc-12d5f261c7bb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Salente, la ville qu’on corrige","competence":"analyser-texte","situation":"Télémaque cherche son père, mais le voyage est aussi une leçon de gouvernement. Lis cette courte notice écrite pour l’exercice, puis trie les réformes de Mentor.","documents":[{"id":"notice","type":"texte","genre":"article","titre":"Un voyage-leçon","blocs":["Télémaque, fils d’Ulysse, parcourt la Méditerranée pour retrouver son père. À ses côtés, Mentor lui donne des leçons ; il est en réalité la déesse Minerve.","À Salente, le roi Idoménée a laissé le luxe ruiner son royaume. Mentor lui conseille de réduire le commerce de luxe, de développer l’agriculture et de simplifier sa cour."],"source":"Notice écrite pour l’exercice"}],"questions":[{"enonce":"Touche le nom du guide de Télémaque.","aide":"C’est celui qui donne les leçons, au côté du jeune prince.","type":"zone","document":"notice","multiple":false},{"enonce":"Touche la ville où Mentor réforme le royaume d’Idoménée.","aide":"Cherche le nom de la cité, dans le second paragraphe.","type":"zone","document":"notice","multiple":false},{"enonce":"Range ce que Mentor réduit et ce qu’il développe à Salente.","aide":"Relis les verbes de la notice : « réduire » d’un côté, « développer » de l’autre.","type":"categories","categories":[{"id":"c0","texte":"Mentor réduit"},{"id":"c1","texte":"Mentor développe"}],"items":[{"id":"i0","texte":"Le faste de la cour"},{"id":"i1","texte":"Le commerce de luxe"},{"id":"i2","texte":"L’agriculture"},{"id":"i3","texte":"Le travail de la terre"}]},{"enonce":"Relie chaque étape du voyage à ce qu’elle enseigne.","aide":"Chaque étape du voyage donne une leçon différente au futur roi.","type":"association","gauche":[{"id":"g0","texte":"Chypre"},{"id":"g1","texte":"L’île de Calypso"},{"id":"g2","texte":"La guerre en Italie"},{"id":"g3","texte":"La Bétique"}],"droite":[{"id":"d0","texte":"Le métier des armes"},{"id":"d1","texte":"L’amour et le renoncement"},{"id":"d2","texte":"La tentation des plaisirs"},{"id":"d3","texte":"Une société pastorale, sans luxe ni propriété"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**Mentor** guide Télémaque ; derrière lui se cache la déesse Minerve."},{"cle":{"type":"zone","ids":["m27"]},"explication":"À **Salente**, Mentor réforme le royaume sous les yeux du lecteur."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Mentor **réduit** le commerce de luxe et le faste de la cour ; il **développe** l’agriculture et le travail de la terre."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**Chypre** : les plaisirs ; **Calypso** : l’amour et le renoncement ; l’**Italie** : les armes ; la **Bétique** : une vie simple et pastorale."}]$ex$::jsonb),
  ('3b54cb3b-8deb-543c-9abc-12d5f261c7bb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le roi que les lois gouvernent","competence":"argumenter","situation":"Inès et Tom se disputent : le *Télémaque* est-il un simple récit mythologique ? Lis leur échange, la phrase de Mentor et le tableau pour construire ton argument.","documents":[{"id":"phrase","type":"texte","genre":"article","titre":"Un mot de Mentor","blocs":["« Il peut tout sur les peuples ; mais les lois peuvent tout sur lui. »"],"source":"Fénelon, *Les Aventures de Télémaque* (1699), Mentor à propos du roi de Crète — phrase donnée par le cours"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Le Télémaque n’est qu’un récit mythologique, une suite d’aventures grecques."},{"qui":"Tom","texte":"À la cour, on l’a lu comme une critique du règne de Louis XIV, et Fénelon y a perdu la faveur du roi."},{"qui":"Inès","texte":"Mais l’histoire se passe dans l’Antiquité !"},{"qui":"Tom","texte":"Justement : une fiction plaisante peut faire passer une leçon politique."}]},{"id":"these","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le livre est un apologue politique","Une fiction plaisante sert une leçon sur le bon gouvernement","?"],["Il fut lu comme une critique du règne","La guerre, le luxe, l’orgueil, les courtisans sont visés","La disgrâce définitive de Fénelon"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne ce qui limite le pouvoir du roi.","aide":"Le roi peut tout sur les peuples, mais pas sur ce qui s’impose à lui.","type":"zone","document":"phrase","multiple":false},{"enonce":"Que dit cette phrase du pouvoir royal ?","aide":"Relis la fin de la phrase : qui peut tout sur le roi ?","type":"choix","options":[{"id":"a","texte":"Il est absolu et sans limite"},{"id":"b","texte":"Il est limité par les lois"},{"id":"c","texte":"Il est partagé avec le peuple"},{"id":"d","texte":"Il est confié à un conseiller"}],"multiple":false},{"enonce":"Quel exemple du roman va dans la case « ? » du tableau ?","aide":"Il faut un épisode où l’on voit un roi corrigé par de bons conseils.","type":"choix","options":[{"id":"a","texte":"Salente, où Mentor réforme le royaume d’Idoménée"},{"id":"b","texte":"La passion de Télémaque pour la nymphe Eucharis"},{"id":"c","texte":"L’île de Calypso, où la passion retient Télémaque"},{"id":"d","texte":"Le voyage à Chypre, qui tente par les plaisirs"}],"multiple":false},{"enonce":"Relie chaque notion à ce qu’elle désigne.","aide":"Pense au rôle de chaque mot dans la dissertation sur le livre.","type":"association","gauche":[{"id":"g0","texte":"Apologue"},{"id":"g1","texte":"Roman d’éducation"},{"id":"g2","texte":"Épopée en prose"},{"id":"g3","texte":"Critique du règne"}],"droite":[{"id":"d0","texte":"Une fiction plaisante au service d’une leçon"},{"id":"d1","texte":"Un jeune héros qui apprend en voyageant"},{"id":"d2","texte":"La guerre, le luxe et les courtisans visés"},{"id":"d3","texte":"Un récit qui prolonge l’*Odyssée*"}]},{"enonce":"Pour quel sujet de dissertation ce livre est-il utile ?","aide":"Le livre est écrit pour un prince et lu comme une critique du roi.","type":"choix","options":[{"id":"a","texte":"Le lyrisme amoureux au XVIe siècle"},{"id":"b","texte":"Le théâtre de l’absurde après 1950"},{"id":"c","texte":"La poésie engagée contre un empereur"},{"id":"d","texte":"La littérature face au pouvoir"}],"multiple":false}]}$ex$::jsonb,
