   $ex${"titre":"Je te hais, donc je me hais","competence":"argumenter","situation":"Maya et Idriss débattent de la pièce. Lis la scène ci-dessous, écrite pour l’exercice à la manière de Genet, puis leur échange, et fais ton choix.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Un soir de cérémonie","blocs":[{"didascalie":"Une chambre. Sur le lit, une robe de soie. Un réveil est posé sur la table."},{"personnage":"Solange","replique":"Tiens-toi droite : ce soir, c’est toi Madame. Moi, je suis la bonne."},{"personnage":"Claire","replique":"Je te regarde et je vois ma propre figure. Quand je te hais, je me hais."},{"personnage":"Solange","replique":"Chut. Le réveil va sonner avant la fin."}],"source":"Texte écrit pour l’exercice, à la manière des *Bonnes* de Genet"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Maya","emoji":"👧","cote":"gauche"},{"nom":"Idriss","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Maya","texte":"Genet met en scène l’affaire des sœurs Papin : c’est un fait divers sur scène."},{"qui":"Idriss","texte":"Non : les sœurs jouent des rôles, c’est une cérémonie. Le fait divers n’est qu’un point de départ."},{"qui":"Maya","texte":"Alors pourquoi ce réveil sur la table ?"},{"qui":"Idriss","texte":"Il interrompt le jeu : la cérémonie ne va jamais jusqu’au bout."}]}],"questions":[{"enonce":"Touche les deux verbes qui montrent que la haine de l’autre se retourne contre soi.","aide":"Le même verbe revient deux fois dans la réplique de Claire.","type":"zone","document":"scene","multiple":true},{"enonce":"Touche l’objet qui annonce la fin de la cérémonie.","aide":"Solange l’évoque à la dernière réplique.","type":"zone","document":"scene","multiple":false},{"enonce":"Quelle lecture de la pièce le débat soutient-il, et le texte confirme-t-il ?","aide":"Relis les mots d’Idriss et la distribution des rôles de Solange.","type":"choix","options":[{"id":"a","texte":"Un drame réaliste sur le travail domestique"},{"id":"b","texte":"Un procès rejoué devant le public du théâtre"},{"id":"c","texte":"Une cérémonie de rôles, pas un fait divers"},{"id":"d","texte":"Un fait divers reconstitué sans aucun artifice"}],"multiple":false},{"enonce":"Relie chaque procédé de la pièce à son effet.","aide":"Pour chaque procédé, cherche ce qu’il fait ressentir au spectateur.","type":"association","gauche":[{"id":"g0","texte":"Le théâtre dans le théâtre"},{"id":"g1","texte":"Le réveil qui sonne"},{"id":"g2","texte":"Une langue somptueuse"},{"id":"g3","texte":"Madame, gentille et légère"}],"droite":[{"id":"d0","texte":"Il pose la question : qui suis-je quand je joue l’autre ?"},{"id":"d1","texte":"Sa gentillesse humilie les deux bonnes"},{"id":"d2","texte":"Il interrompt la cérémonie avant le meurtre"},{"id":"d3","texte":"Elle donne de la grandeur à des humiliées"}]},{"enonce":"Que désigne la « domination intériorisée » dans la pièce ?","aide":"Reviens à la phrase de Claire sur sa propre figure.","type":"choix","options":[{"id":"a","texte":"Madame domine les bonnes par la force physique"},{"id":"b","texte":"Les bonnes se révoltent ouvertement contre Madame"},{"id":"c","texte":"Les bonnes haïssent Madame, mais se haïssent en elle"},{"id":"d","texte":"Monsieur impose sa loi depuis la prison"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m41","m44"]},"explication":"Les deux **hais** disent la domination intériorisée : en haïssant l’autre, Claire se hait elle-même."},{"cle":{"type":"zone","ids":["m47"]},"explication":"Le **réveil** interrompt la cérémonie avant qu’elle n’aille jusqu’au bout."},{"cle":{"type":"choix","ids":["c"]},"explication":"La pièce est une **cérémonie** : les sœurs jouent des **rôles**, et c’est cela qui compte plus que le fait divers."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"Le **jeu de rôles** interroge l’identité, le **réveil** retarde le crime, la **langue somptueuse** honore les humiliées, la **gentillesse** de Madame humilie."},{"cle":{"type":"choix","ids":["c"]},"explication":"La domination est **intériorisée** quand les bonnes haïssent Madame **mais se haïssent en elle**."}]$ex$::jsonb),
