  ('c0f64c4c-2721-576c-b8d4-25c798d04a74'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le journal d’un double","competence":"argumenter","situation":"Anaïs et Léo débattent : ce livre est-il l’autobiographie de Gide ? Lis la page de journal écrite pour l’exercice et leur échange, puis fais le tri.","documents":[{"id":"page","type":"texte","genre":"lettre","titre":"Une page de journal","blocs":["Cahier blanc. — Je n’ai pas touché sa main. J’ai écrit toute la nuit : l’écriture remplace ce que je refuse à mon corps.","Mère, j’ai tenu ma promesse. Je lis la Bible et je ne dors plus."],"source":"Texte écrit pour l’exercice, à la manière des *Cahiers d’André Walter* de Gide"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Anaïs","emoji":"👧","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anaïs","texte":"Gide raconte sa propre vie : c’est une autobiographie."},{"qui":"Léo","texte":"C’est un journal fictif : Walter est un double de Gide, pas Gide lui-même."},{"qui":"Anaïs","texte":"Pourtant Madeleine est bien la vraie Emmanuèle."},{"qui":"Léo","texte":"Oui, mais Walter meurt fou, alors que Gide écrit pour convaincre sa cousine de l’épouser."}]}],"questions":[{"enonce":"Touche le mot qui dit ce qui remplace la vie dans cette page.","aide":"Walter ne touche pas la main de sa cousine : que fait-il de ses nuits ?","type":"zone","document":"page","multiple":false},{"enonce":"Range chaque élément selon la tension du livre.","aide":"Walter choisit l’amour pur : il refuse l’un pour vivre dans l’autre.","type":"categories","categories":[{"id":"c0","texte":"Du côté du corps"},{"id":"c1","texte":"Du côté de l’esprit"}],"items":[{"id":"i0","texte":"L’écriture du journal"},{"id":"i1","texte":"La main de la cousine"},{"id":"i2","texte":"Le désir"},{"id":"i3","texte":"La mystique"},{"id":"i4","texte":"La lecture de la Bible"}]},{"enonce":"Quelle lecture le débat soutient-il ?","aide":"Relis la réponse de Léo.","type":"choix","options":[{"id":"a","texte":"Un journal fictif où Walter est le double de Gide"},{"id":"b","texte":"Une autobiographie fidèle de Gide, jour après jour"},{"id":"c","texte":"Un roman historique sur la Réforme protestante"},{"id":"d","texte":"Un essai philosophique sans personnage"}],"multiple":false},{"enonce":"Relie chaque procédé du livre à son effet.","aide":"Chaque procédé a une fonction dans la construction du récit.","type":"association","gauche":[{"id":"g0","texte":"Le journal fictif"},{"id":"g1","texte":"Le roman dans le roman (Allain)"},{"id":"g2","texte":"Le style symboliste"},{"id":"g3","texte":"La promesse à la mère"}],"droite":[{"id":"d0","texte":"La loi morale qui pèse même après sa mort"},{"id":"d1","texte":"Roman à la première personne, avec un double de l’auteur"},{"id":"d2","texte":"Le héros reflète Walter, son créateur"},{"id":"d3","texte":"Marque d’une période que Gide jugera sévèrement"}]},{"enonce":"Que devient la tension entre le corps et l’esprit dans la suite de l’œuvre ?","aide":"Le cours dit que ce livre est la matrice de toute l’œuvre.","type":"choix","options":[{"id":"a","texte":"Elle disparaît définitivement après ce premier livre"},{"id":"b","texte":"Elle ne concerne que les soties, comme les *Caves*"},{"id":"c","texte":"Elle revient dans *L’Immoraliste* et *La Porte étroite*"},{"id":"d","texte":"Elle ne reparaît que dans les *Faux-Monnayeurs*"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"L’**écriture** remplace la vie : c’est la sublimation qui structure le livre."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c1"}},"explication":"La **main** et le **désir** relèvent du corps ; la **Bible**, l’**écriture** et la **mystique** de l’esprit."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le livre est un **journal fictif** : Walter est le **double** de Gide, pas Gide lui-même."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"Le **journal** crée le double, **Allain** le reflète, le **style** date le livre, la **promesse** est la loi de la mère."},{"cle":{"type":"choix","ids":["c"]},"explication":"La tension se retrouve dans *L’Immoraliste* et *La Porte étroite* : le livre est la **matrice** de l’œuvre."}]$ex$::jsonb),
