   $ex${"titre":"Un adolescent à Douai","competence":"se-reperer-temps","situation":"Pour ta fiche sur *Les Cahiers de Douai*, situe le recueil dans la vie de Rimbaud, puis relève ce qu’il faut savoir sur sa composition.","documents":[{"id":"frise","type":"frise","titre":"Rimbaud et le recueil","debut":1850,"fin":1895,"pas":5,"evenements":[{"id":"z1","date":1854,"nom":"Naissance"},{"id":"z2","date":1870,"nom":"Douai"},{"id":"z3","date":1891,"nom":"Mort"}]}],"questions":[{"enonce":"Touche l’année où Rimbaud recopie ses poèmes à Douai.","aide":"C’est l’automne de la guerre franco-prussienne.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le séjour à Douai de la mort de Rimbaud ?","aide":"Repère « Douai » et « Mort » sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"À qui Rimbaud confie-t-il les poèmes recopiés ?","aide":"Un jeune poète rencontré à Douai, à qui il espère être publié.","type":"choix","options":[{"id":"a","texte":"À Paul Demeny"},{"id":"b","texte":"À Georges Izambard"},{"id":"c","texte":"À Paul Verlaine"},{"id":"d","texte":"À Stéphane Mallarmé"}],"multiple":false},{"enonce":"Complète la carte d’identité du recueil.","aide":"Le titre n’a pas été donné par le poète lui-même.","type":"trous","segments":["Vingt-deux poèmes recopiés à ",0," à l’automne ",1," ; le titre est ",2,"."],"banque":["Douai","choisi par Rimbaud","Charleville","posthume","1870","1871"]}]}$ex$::jsonb,
