   $ex${"titre":"Deux trous rouges au côté droit","competence":"argumenter","situation":"Chloé et Sami discutent du « Dormeur du val ». Lis les vers choisis, puis leur débat, et tranche.","documents":[{"id":"vers","type":"texte","genre":"poeme","titre":"Le premier vers et la chute","blocs":["C’est un trou de verdure où chante une rivière,","","Il dort dans le soleil, la main sur sa poitrine,","Tranquille. Il a deux trous rouges au côté droit."],"source":"Arthur Rimbaud, « Le Dormeur du val » (1870), vers 1, 13 et 14"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Chloé","emoji":"👧","cote":"gauche"},{"nom":"Sami","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Chloé","texte":"Ce poème décrit un jeune soldat qui fait la sieste dans un joli paysage."},{"qui":"Sami","texte":"Regarde la fin : il est mort, et le calme du décor le cachait jusque-là."},{"qui":"Chloé","texte":"Alors la guerre n’apparaît presque pas ?"},{"qui":"Sami","texte":"Elle surgit d’un coup dans la chute, par les deux trous rouges."}]}],"questions":[{"enonce":"Touche les deux mots qui révèlent que le soldat est mort.","aide":"Cherche la blessure, à la dernière ligne.","type":"zone","document":"vers","multiple":true},{"enonce":"Quel effet la chute produit-elle sur le lecteur ?","aide":"Relis le premier vers, puis la dernière ligne.","type":"choix","options":[{"id":"a","texte":"Elle décrit un souvenir d’enfance du poète"},{"id":"b","texte":"Elle renverse le calme du décor par la violence de la guerre"},{"id":"c","texte":"Elle introduit un moment de comédie légère"},{"id":"d","texte":"Elle confirme que le soldat se repose tranquillement"}],"multiple":false},{"enonce":"Relie chaque élément du poème à son effet.","aide":"Pense à la forme, au décor, puis à la fin.","type":"association","gauche":[{"id":"g0","texte":"La forme du sonnet"},{"id":"g1","texte":"Le décor de la nature"},{"id":"g2","texte":"La chute « deux trous rouges »"}],"droite":[{"id":"d0","texte":"La révélation brutale de la guerre"},{"id":"d1","texte":"Un calme qui cache la mort"},{"id":"d2","texte":"Un moule noble pour un sujet violent"}]},{"enonce":"Quelle formule résume le rapport de Rimbaud aux formes héritées ?","aide":"Dans le cours : « il maîtrise ET il maltraite ».","type":"choix","options":[{"id":"a","texte":"Il rejette totalement la forme du sonnet"},{"id":"b","texte":"Il maîtrise le vers classique et le maltraite"},{"id":"c","texte":"Il n’écrit que des vers libres, sans rime"},{"id":"d","texte":"Il imite fidèlement ses maîtres parnassiens"}],"multiple":false},{"enonce":"Quel texte de 1871 ces poèmes préparent-ils ?","aide":"Le poète veut se faire « voyant ».","type":"choix","options":[{"id":"a","texte":"Les Poètes maudits, de Verlaine"},{"id":"b","texte":"Les Illuminations"},{"id":"c","texte":"La lettre du Voyant"},{"id":"d","texte":"Une saison en enfer"}],"multiple":false}]}$ex$::jsonb,
