  ('bb563c92-369f-5a0f-9767-3a1883aad36c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le riche, le pauvre et le distrait","competence":"analyser-texte","situation":"La Bruyère montre au lieu de démontrer. Lis ce portrait écrit pour l’exercice à sa manière, puis relie les portraits du livre à leur caractère.","documents":[{"id":"portrait","type":"texte","genre":"recit","titre":"Deux hommes à la même table","blocs":["Arsène occupe tout l’espace : il parle haut, il fait répéter son voisin et ne goûte qu’à demi ce qu’on lui dit. On l’écoute, parce qu’il est riche.","Lycas se fait petit : il n’ose rien demander, il baisse les yeux et s’excuse d’être là. On ne l’écoute pas, parce qu’il est pauvre."],"source":"Texte écrit pour l’exercice, à la manière des portraits de La Bruyère"}],"questions":[{"enonce":"Touche le mot qui montre comment parle le riche.","aide":"Le riche prend de la place par sa voix.","type":"zone","document":"portrait","multiple":false},{"enonce":"Touche le mot qui montre que le pauvre n’ose pas.","aide":"Il n’ose pas demander quoi que ce soit.","type":"zone","document":"portrait","multiple":false},{"enonce":"Relie chaque portrait de La Bruyère à son caractère.","aide":"Les deux premiers se retrouvent dans le texte ; les deux autres sont dans le cours.","type":"association","gauche":[{"id":"g0","texte":"Giton"},{"id":"g1","texte":"Phédon"},{"id":"g2","texte":"Ménalque"},{"id":"g3","texte":"Les paysans"}],"droite":[{"id":"d0","texte":"Des « animaux farouches » qui se révèlent des hommes"},{"id":"d1","texte":"Le riche, qui parle haut et occupe l’espace"},{"id":"d2","texte":"Le pauvre, qui se fait petit et n’ose rien"},{"id":"d3","texte":"Le distrait, qui oublie jusqu’à son mariage"}]},{"enonce":"Pourquoi les personnages des *Caractères* portent-ils des noms grecs ?","aide":"La cour s’y reconnaissait, des « clés » circulaient.","type":"choix","options":[{"id":"a","texte":"Pour rendre hommage aux dieux de la mythologie"},{"id":"b","texte":"Parce que La Bruyère a traduit tout le livre du grec"},{"id":"c","texte":"Parce que le livre se passe dans la Grèce antique"},{"id":"d","texte":"Pour protéger l’auteur et laisser reconnaître les modèles"}],"multiple":false}]}$ex$::jsonb,
