ple":false},{"enonce":"Range chaque élément : forme brève du livre ou ce qu’il n’est pas.","aide":"Le livre compte plus de mille remarques courtes.","type":"categories","categories":[{"id":"c0","texte":"Forme brève du livre"},{"id":"c1","texte":"Ce que le livre n’est pas"}],"items":[{"id":"i0","texte":"Une démonstration suivie en trois parties"},{"id":"i1","texte":"Un portrait"},{"id":"i2","texte":"Un long traité philosophique"},{"id":"i3","texte":"Une maxime"}]},{"enonce":"Pourquoi *Les Caractères* sert-il pour la littérature d’idées ?","aide":"La Bruyère procède par remarques brèves et par portraits.","type":"choix","options":[{"id":"a","texte":"Il raconte une histoire suivie sur plusieurs actes"},{"id":"b","texte":"Il met en vers les règles de la grammaire"},{"id":"c","texte":"Il critique la société sans jamais argumenter longuement"},{"id":"d","texte":"Il expose un système philosophique complet"}],"multiple":false}]}$ex$::jsonb,
