emain"}],"multiple":false},{"enonce":"Relie chaque élément du livre à son effet.","aide":"Chaque élément joue un rôle dans la réception ou la construction du livre.","type":"association","gauche":[{"id":"g0","texte":"Les surréalistes"},{"id":"g1","texte":"Julius, romancier"},{"id":"g2","texte":"Le ton de sotie"},{"id":"g3","texte":"Le remords de Lafcadio"}],"droite":[{"id":"d0","texte":"Il moque la religion, la crédulité et le romanesque"},{"id":"d1","texte":"Ils ont adoré l’idée d’acte gratuit"},{"id":"d2","texte":"Il relativise l’idée d’un acte sans conséquence"},{"id":"d3","texte":"Il annonce la mise en abyme des *Faux-Monnayeurs*"}]},{"enonce":"Pour quel sujet de dissertation l’acte gratuit est-il utile ?","aide":"Le cours évoque une question précise sur la liberté.","type":"choix","options":[{"id":"a","texte":"La liberté et la responsabilité d’un acte"},{"id":"b","texte":"Théâtre de l’absurde et parole impuissante"},{"id":"c","texte":"Lyrisme amoureux et fuite du temps"},{"id":"d","texte":"Poésie engagée contre un régime"}],"multiple":false}]}$ex$::jsonb,
