ide":"Une moquerie, une épopée, une émotion, un refrain.","type":"association","gauche":[{"id":"g0","texte":"Registre satirique"},{"id":"g1","texte":"Registre épique"},{"id":"g2","texte":"Registre pathétique"},{"id":"g3","texte":"Registre populaire"}],"droite":[{"id":"d0","texte":"« Souvenir de la nuit du 4 » : un enfant tué"},{"id":"d1","texte":"« Chanson » : des refrains faits pour circuler"},{"id":"d2","texte":"Le surnom « Napoléon le Petit »"},{"id":"d3","texte":"« L’expiation » : Waterloo et Sainte-Hélène"}]},{"enonce":"Pourquoi Hugo refuse-t-il l’amnistie de 1859 ?","aide":"Le cours cite sa phrase sur le retour de la liberté.","type":"choix","options":[{"id":"a","texte":"Il craint de perdre son titre de poète national"},{"id":"b","texte":"Il préfère rester vivre à Bruxelles, en sécurité"},{"id":"c","texte":"Il n’a pas été informé de la mesure à temps"},{"id":"d","texte":"Il ne rentrera que « quand la liberté rentrera »"}],"multiple":false}]}$ex$::jsonb,
