   $ex${"titre":"Peut-on tout dire de soi ?","competence":"argumenter","situation":"Pour ta dissertation, tu travailles le début des *Confessions* et un débat entre deux lecteurs : Rousseau avoue-t-il tout, ou plaide-t-il ?","documents":[{"id":"pr","type":"texte","genre":"recit","titre":"Le début du livre","blocs":["Je forme une entreprise qui n’eut jamais d’exemple et dont l’exécution n’aura point d’imitateur.","Je veux montrer à mes semblables un homme dans toute la vérité de la nature ; et cet homme, ce sera moi."],"source":"Jean-Jacques Rousseau, *Les Confessions* (1782), début du livre I"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Rousseau avoue ses fautes, donc il dit tout et rien que la vérité."},{"qui":"Théo","texte":"Il avoue, mais il plaide aussi : il écrit pour se justifier devant les calomnies."},{"qui":"Inès","texte":"Alors le livre est une défense autant qu’un aveu ?"},{"qui":"Théo","texte":"Oui, et c’est tout l’intérêt de la question : peut-on tout dire de soi ?"}]}],"questions":[{"enonce":"Touche les deux mots qui disent la valeur promise au lecteur et le seul sujet du livre.","aide":"Un nom de qualité, puis un pronom de la première personne.","type":"zone","document":"pr","multiple":true},{"enonce":"Touche le verbe par lequel Théo montre que Rousseau ne fait pas que s’accuser.","aide":"Théo l’emploie dès sa première réplique.","type":"zone","document":"deb","multiple":false},{"enonce":"Range chaque trait : le narrateur adulte qui juge, ou l’enfant qui vit.","aide":"L’adulte commente ; l’enfant éprouve.","type":"categories","categories":[{"id":"c0","texte":"Le narrateur adulte qui juge"},{"id":"c1","texte":"L’enfant qui vit"}],"items":[{"id":"i0","texte":"Il reçoit la fessée de Mlle Lambercier"},{"id":"i1","texte":"Il plaide pour sa défense"},{"id":"i2","texte":"Il analyse après coup l’épisode du ruban"},{"id":"i3","texte":"Il se présente devant « le souverain juge »"},{"id":"i4","texte":"Il lit des romans à Genève"},{"id":"i5","texte":"Il fugue de sa ville natale"}]},{"enonce":"Quelle réponse le livre apporte-t-il le mieux à la question « peut-on tout dire de soi ? »","aide":"Pense au mot « plaide » de Théo.","type":"choix","options":[{"id":"a","texte":"Rousseau cache ses fautes pour séduire son lecteur"},{"id":"b","texte":"Rousseau renonce à parler de son enfance et de ses amis"},{"id":"c","texte":"Rousseau s’interdit tout jugement sur ses propres actes"},{"id":"d","texte":"Rousseau avoue ses fautes, mais il plaide aussi pour sa défense"}],"multiple":false}]}$ex$::jsonb,
