   $ex${"titre":"Un chemin vers une tombe","competence":"analyser-texte","situation":"Tu prépares l’explication d’un poème de deuil. Lis quatre vers, relève ce qu’ils disent du marcheur, puis relie quelques poèmes du recueil à ce qu’ils portent.","documents":[{"id":"p","type":"texte","genre":"poeme","titre":"Demain, dès l’aube…","blocs":["Je marcherai les yeux fixés sur mes pensées,","Sans rien voir au dehors, sans entendre aucun bruit,","Seul, inconnu, le dos courbé, les mains croisées,","Triste, et le jour pour moi sera comme la nuit."],"source":"Victor Hugo, « Demain, dès l’aube… », *Les Contemplations* (1856), livre IV, vers 3 à 6"}],"questions":[{"enonce":"Touche les deux mots qui décrivent le corps du marcheur.","aide":"Regarde le troisième vers.","type":"zone","document":"p","multiple":true},{"enonce":"Touche le mot qui dit que le monde a perdu sa lumière pour lui.","aide":"Le dernier vers compare le jour à autre chose.","type":"zone","document":"p","multiple":false},{"enonce":"Que montre le vers « Sans rien voir au dehors, sans entendre aucun bruit » ?","aide":"Le poète ne regarde pas dehors : il regarde autre chose.","type":"choix","options":[{"id":"a","texte":"Le poète cherche un peu de bruit pour se distraire"},{"id":"b","texte":"Le poète craint d’être suivi par des inconnus en route"},{"id":"c","texte":"Le poète marche replié sur sa douleur, coupé du monde"},{"id":"d","texte":"Le poète observe avec soin la campagne qu’il traverse"}],"multiple":false},{"enonce":"Relie chaque poème du recueil à ce qu’il porte.","aide":"Un poème social, un poème de révolte littéraire, un deuil, une méditation.","type":"association","gauche":[{"id":"g0","texte":"« Réponse à un acte d’accusation »"},{"id":"g1","texte":"« Melancholia »"},{"id":"g2","texte":"« Demain, dès l’aube… »"},{"id":"g3","texte":"« Paroles sur la dune »"}],"droite":[{"id":"d0","texte":"Le « bonnet rouge » mis au vieux dictionnaire"},{"id":"d1","texte":"Le deuil : une marche vers la tombe de la fille"},{"