   $ex${"titre":"Un enfant qui lit avant de comprendre","competence":"analyser-texte","situation":"Lis une courte scène écrite pour l’exercice, à la manière du livre, puis dis ce que Sartre adulte pense de cet enfant.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Dans la bibliothèque","blocs":["Dans la bibliothèque de son grand-père, un petit garçon déchiffre des livres trop grands pour lui. Il ne comprend pas tout, mais il sent qu’on l’observe : les adultes sourient dès qu’il ouvre un volume.","Alors il joue le rôle de l’enfant prodige, et il finit par se croire destiné à écrire."],"source":"Texte écrit pour l’exercice, à la manière des *Mots* de Sartre"},{"id":"regard","type":"tableau","titre":"Le regard rétrospectif","colonnes":["Ce que le livre n’est pas","Ce qu’il est"],"lignes":[["Une œuvre nostalgique","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe qui dit ce que l’enfant fait des livres sans toujours les comprendre.","aide":"Il lit avant de comprendre : quel verbe le dit ?","type":"zone","document":"scene","multiple":false},{"enonce":"Touche le mot qui dit ce que l’enfant finit par se persuader.","aide":"Pense à la vocation, ce que le narrateur adulte appelle une illusion.","type":"zone","document":"scene","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Le narrateur adulte se moque de l’enfant qu’il était.","type":"choix","options":[{"id":"a","texte":"Une plainte contre les professeurs"},{"id":"b","texte":"Un hommage tendre à la famille"},{"id":"c","texte":"Une démolition de la comédie jouée enfant"},{"id":"d","texte":"Un retour ému vers le paradis perdu"}],"multiple":false},{"enonce":"Remets dans l’ordre le parcours que le livre raconte.","aide":"On part de l’enfant et on termine par le regard de l’adulte.","type":"ordre","items":[{"id":"a","texte":"L’enfant lit avant de comprendre"},{"id":"b","texte":"Adulte, il juge cette vocation illusoire"},{"id":"c","texte":"Il se persuade qu’il est destiné à écrire"},{"id":"d","texte":"Il joue l’enfant prodige"}]}]}$ex$::jsonb,
