   $ex${"titre":"Une cité qui pleure sans l’avoir voulu","competence":"argumenter","situation":"Lis une scène écrite pour l’exercice, à la manière de la pièce, puis dis ce qu’elle montre de la liberté et du pouvoir.","documents":[{"id":"sc","type":"texte","genre":"theatre","titre":"Sur la place","blocs":[{"didascalie":"Sur la place d’une ville couverte d’insectes, un étranger s’adresse à un vieux prêtre."},{"personnage":"L’étranger","replique":"Vous pleurez une faute que vous n’avez pas commise."},{"personnage":"Le prêtre","replique":"C’est la loi de la cité : chacun doit se repentir."},{"personnage":"L’étranger","replique":"Une loi qui fabrique des coupables sert celui qui gouverne."},{"personnage":"Le prêtre","replique":"Et si l’on refuse de pleurer ?"},{"personnage":"L’étranger","replique":"Alors on est enfin libre."}],"source":"Texte écrit pour l’exercice, à la manière des *Mouches* de Sartre"},{"id":"plan","type":"tableau","titre":"Un plan à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Sartre réécrit un mythe pour parler de son temps","Il garde l’histoire mais change le sens","?"],["La pièce défend la liberté contre toute autorité","Oreste refuse le pardon de Jupiter","Il quitte Argos en entraînant les mouches"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que le peuple est innocent de ce qu’on lui fait pleurer.","aide":"Quelle faute le prêtre dit-il commise ?","type":"zone","document":"sc","multiple":false},{"enonce":"Touche le verbe qui désigne celui que sert, selon l’étranger, le remords imposé.","aide":"Qui profite d’un peuple coupable ?","type":"zone","document":"sc","multiple":false},{"enonce":"Quelle lecture ce passage permet-il de prouver ?","aide":"Qui profite de ce que le peuple pleure sans avoir fait de faute ?","type":"choix","options":[{"id":"a","texte":"Le repentir est la plus haute des vertus"},{"id":"b","texte":"Le remords imposé est un moyen de tenir un peuple"},{"id":"c","texte":"Les dieux punissent justement les hommes"},{"id":"d","texte":"Le prêtre cherche à protéger l’étranger"}],"multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Il faut une pièce de Sartre qui réécrit un mythe.","type":"choix","options":[{"id":"a","texte":"L’Être et le Néant, publié par Sartre en 1943"},{"id":"b","texte":"Les Mouches, créée sous l’Occupation, en 1943"},{"id":"c","texte":"Les Choéphores d’Eschyle, tragédie antique"},{"id":"d","texte":"Les Mots, autobiographie parue en 1964"}],"multiple":false}]}$ex$::jsonb,
