   $ex${"titre":"Familles, je vous hais !","competence":"analyser-texte","situation":"Lis deux passages authentiques du livre, puis relie ses figures à leurs rôles.","documents":[{"id":"tx","type":"texte","genre":"recit","titre":"Deux appels","blocs":["Familles, je vous hais ! foyers clos ; portes refermées ; possessions jalouses du bonheur.","Nathanaël, à présent jette mon livre."],"source":"André Gide, *Les Nourritures terrestres* (1897)"},{"id":"fig","type":"tableau","titre":"Les figures du livre","colonnes":["Figure","Son rôle"],"lignes":[["Nathanaël","Le disciple à qui l’on parle, c’est-à-dire le lecteur"],["Ménalque","Le maître qui a tout quitté pour vivre intensément"],["Le narrateur","Un ancien malade qui réapprend à sentir"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les trois mots qui disent l’enfermement de la famille.","aide":"Cherche ce qui est fermé ou jaloux.","type":"zone","document":"tx","multiple":true},{"enonce":"Touche le verbe de l’ordre final donné à Nathanaël.","aide":"Que doit faire Nathanaël du livre ?","type":"zone","document":"tx","multiple":false},{"enonce":"Relie chaque figure du livre à son rôle.","aide":"Regarde le tableau.","type":"association","gauche":[{"id":"g0","texte":"Nathanaël"},{"id":"g1","texte":"Ménalque"},{"id":"g2","texte":"Le narrateur"}],"droite":[{"id":"d0","texte":"Le maître qui a tout quitté"},{"id":"d1","texte":"Un ancien malade qui réapprend à sentir"},{"id":"d2","texte":"Le disciple à qui l’on parle"}]},{"enonce":"Que refuse Gide dans la formule « Familles, je vous hais ! » ?","aide":"Regarde les mots qui suivent l’exclamation.","type":"choix","options":[{"id":"a","texte":"Les poèmes écrits en vers réguliers et rimés"},{"id":"b","texte":"Les voyages et les villes d’Afrique du Nord"},{"id":"c","texte":"Les attaches : famille, habitudes, possessions"},{"id":"d","texte":"Les amis qui admirent et lisent ses livres"}],"multiple":false}]}$ex$::jsonb,
